public RestaurantMenuModuleWindow(RestaurantMenuModuleView moduleView) {
    super(moduleView, new ResourceLocation("minecolonies", "gui/layouthuts/layoutfoodstock.xml"));
    this.menuList = (ScrollingList)this.window.findPaneOfTypeByID("resourcesstock", ScrollingList.class);
    this.registerButton("switch", this::switchClicked);
    this.registerButton("removeStock", this::removeStock);
    this.resourceList = (ScrollingList)this.window.findPaneOfTypeByID("resources", ScrollingList.class);
    this.groupedItemList = new ArrayList<ItemStorage>(IColonyManager.getInstance().getCompatibilityManager().getEdibles(moduleView.getBuildingView().getBuildingLevel() - 1));
    ((TextField)this.window.findPaneOfTypeByID("input", TextField.class)).setHandler(input -> {
        String newFilter = input.getText();
        if (!newFilter.equals(this.filter)) {
            this.filter = newFilter;
            this.tick = 10;
        }
    });
    IBuildingView iBuildingView = moduleView.getBuildingView();
    if (iBuildingView instanceof BuildingCook.View) {
        BuildingCook.View buildingCookView = (BuildingCook.View)iBuildingView;
        double sum = 0.0;
        IntIterator intIterator = buildingCookView.getCustomers().iterator();
        while (intIterator.hasNext()) {
            int i = (Integer)intIterator.next();
            ICitizenDataView citizenDataView = buildingCookView.getColony().getCitizen(i);
            if (citizenDataView == null) continue;
            int buildingLevel = citizenDataView.getHomeBuilding() == null ? 0 : ((IBuildingView)buildingCookView.getColony().getClientBuildingManager().getBuilding(citizenDataView.getHomeBuilding())).getBuildingLevelEquivalent();
            sum += FoodUtils.computeSaturationConsumptionFactor(buildingLevel);
        }
        this.avgCustomerConsumption = sum / (double)buildingCookView.getCustomers().size();
        this.numerOfCustomers = buildingCookView.getCustomers().size();
    }
}

